function printToScreen(text) {
  let r = Math.floor((Math.random() * 155));
  let g = Math.floor((Math.random() * 155));
  let b = Math.floor((Math.random() * 155));
  const svg = d3.select("body")
    .append("svg")
    .attr("width", 1500)
    .attr("height", 75);

  svg.append("text")
    .attr("y", 37.5)
    .attr("width", 450)
    .attr("height", 75)
    .attr("x", -1000)
    .attr("font-weight", "bold")
    .attr("font-size", "24px")
    .attr("fill", `rgb(${r},${g},${b}`)
    .attr("font-family", "Times New Roman")
    .text(text)
    .transition()
    .duration(1000)
    .attr("x", 37.5);
}

// We have a bunch of pennies and want to change them out for bigger bills and coins in order to better sort our money. Have the user enter in how many pennies they have and then calculate how many dollars, quarters, dimes, nickels, and leftover pennies they can make from the original pennies.

// Solution

let pennies = +prompt("Enter in an amount of pennies. ");
let dollars = 0;
let quarters = 0;
let dimes = 0;
let nickels = 0;

while (pennies >= 100){
  pennies -= 100;
  dollars += 1;
}

while (pennies >= 25){
  pennies -= 25;
  quarters += 1;
}

while (pennies >= 10){
  pennies -= 10;
  dimes += 1;
}

while (pennies >= 5){
  pennies -= 5;
  nickels += 1;
}

printToScreen("You have " + dollars + " dollars, " + quarters + " quarters, " + dimes + " dimes, " + nickels + " nickels, and " + pennies + " pennies.");

