// Using a for loop, add the numbers 1 to 100 and print the result. Then, add the squares of all of the numbers from 1 to 100 and print the result. Finally, find the factorial of any positive number that the user inputs and print the result.

// Solution

let total = 0;

for (let i = 1; i <= 100; i++){
  total += i;
}

printToScreen(total);

total = 0;

for (let i = 0; i <= 100; i++){
  total += i * i;
}

printToScreen(total);

let num = +prompt("Please enter a number to calculate the factorial of.")

total = 1;
for (let i = num; i > 1; i--){
  total *= i;
}

printToScreen(total);

